 ("A8",json.loads(r'''"function _memRender(){"'''),json.loads(r'''"// ===== [PA3-v1] 회원 상세 요약 카드 — 행 클릭 시 (운영자 260828 「어떤 회원인지 + 예매 이력·거주지·연령·선호 장르」) =====\n// 데이터 = _memState.rows(회원) × _bkState.by[전화](예매집계 총구매/총매수/총금액/첫·최근/월|장르 분포) — 전부 클라이언트 기존 적재분.\nasync function _memDetail(ph){\n  try{\n    var r=((_memState||{}).rows||[]).find(function(x){return String(x['휴대폰정규화']||x['휴대폰번호']||'').replace(/\\D/g,'')===ph;});\n    if(!r)return;\n    var old=document.getElementById('mem-detail');if(old)old.remove();\n    var maskOn=!!((document.getElementById('mem-mask')||{}).checked);\n    var nm=maskOn?_memMaskName(String(r['이름']||'')):String(r['이름']||'');\n    var phT=ph.length===11?(ph.slice(0,3)+'-'+(maskOn?'****':ph.slice(3,7))+'-'+ph.slice(7)):ph;\n    var addr=[r['주소1'],r['주소2'],r['주소3']].filter(function(x){return x;}).join(' ');\n    var age=String(r['연령대']||'');\n    var wrap=document.createElement('div');wrap.id='mem-detail';\n    wrap.innerHTML='<div class=\"modal-bg show\" onclick=\"if(event.target===this)document.getElementById(\\'mem-detail\\').remove()\"><div class=\"modal\" style=\"width:660px;max-width:94vw;text-align:left\"><button class=\"modal-x\" onclick=\"document.getElementById(\\'mem-detail\\').remove()\" title=\"닫기\" aria-label=\"닫기\">✕</button><div id=\"mem-detail-body\"><div style=\"padding:26px 8px;text-align:center;color:var(--dim);font-size:12.5px\">예매 이력 불러오는 중…</div></div></div></div>';\n    document.body.appendChild(wrap);\n    try{var ml=document.getElementById('member-lookup');var z=ml?parseInt(getComputedStyle(ml).zIndex,10):0;if(z)wrap.firstChild.style.zIndex=String(z+2);}catch(_e){}\n    var bk=null; try{ await _bkLoad(false); bk=(_bkState&&_bkState.by)?(_bkState.by[ph]||null):null; }catch(_e){}\n    var bd=document.getElementById('mem-detail-body'); if(!bd)return;\n    var esc=_memEsc;\n    var head='<div style=\"font-size:16px;font-weight:800;margin-right:30px\">'+esc(nm)+' <span style=\"font-weight:400;color:var(--dim);font-size:12px\">'+esc(phT)+'</span></div>'\n      +'<div style=\"margin-top:5px;font-size:12.5px;color:var(--muted)\">'+(age?'<b style=\"color:var(--accent)\">'+esc(age)+'</b> · ':'')+esc(addr||'주소 없음')+'</div>';\n    if(!bk){ bd.innerHTML=head+'<div style=\"margin-top:18px;padding:16px;border:1px dashed var(--border2);border-radius:var(--r-btn);color:var(--dim);font-size:12.5px\">예매 장부(2015~2026 기획공연 예매이력)에서 이 번호의 기록을 못 찾았어요.</div>'; return; }\n    var gsum={},ysum={},tot=0;\n    for(var k in bk.d){var i=k.indexOf('|');if(i<0)continue;var g=k.slice(i+1),y=k.slice(0,4);var v=bk.d[k]||0;gsum[g]=(gsum[g]||0)+v;ysum[y]=(ysum[y]||0)+v;tot+=v;}\n    var gl=Object.keys(gsum).sort(function(a,b){return gsum[b]-gsum[a];});\n    var chips=gl.map(function(g,i){var on=i===0;return '<span style=\"display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:14px;font-size:12px;font-weight:'+(on?'800':'600')+';background:'+(on?'var(--accent)':'var(--accent-glow)')+';color:'+(on?'#fff':'var(--accent)')+'\">'+esc(g)+' <span style=\"font-variant-numeric:tabular-nums\">'+gsum[g]+'</span></span>';}).join(' ');\n    var years=Object.keys(ysum).sort();\n    var mx=1;years.forEach(function(y){if(ysum[y]>mx)mx=ysum[y];});\n    var bars=years.map(function(y){var h=Math.max(3,Math.round(ysum[y]/mx*46));return '<div style=\"display:flex;flex-direction:column;align-items:center;gap:4px\"><div style=\"font-size:10px;color:var(--dim);font-variant-numeric:tabular-nums\">'+ysum[y]+'</div><div style=\"width:16px;height:'+h+'px;border-radius:4px 4px 2px 2px;background:var(--accent);opacity:'+(0.45+0.55*ysum[y]/mx).toFixed(2)+'\"></div><div style=\"font-size:10px;color:var(--muted)\">'+String(y).slice(2)+'</div></div>';}).join('');\n    var fmt=function(v){return (v||0).toLocaleString();};\n    var dt=function(v){v=String(v||'');return v.length===8?(v.slice(2,4)+'.'+v.slice(4,6)+'.'+v.slice(6)):v;};\n    var tbar='<span style=\"display:inline-block;width:3px;height:11px;border-radius:2px;background:#8B8EF2;margin-right:7px;vertical-align:-1px\"></span>';\n    bd.innerHTML=head\n      +'<div style=\"display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:16px\">'\n      +[['총 예매',fmt(bk.n)+'건'],['총 매수',fmt(bk.tix)+'매'],['총 금액',fmt(bk.amt)+'원'],['기간',dt(bk.first)+' ~ '+dt(bk.last)]].map(function(x){return '<div style=\"padding:10px 12px;background:var(--neutral);border-radius:var(--r-btn)\"><div style=\"font-size:11px;color:var(--neutral-text)\">'+x[0]+'</div><div style=\"margin-top:3px;font-size:13px;font-weight:800;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis\">'+x[1]+'</div></div>';}).join('')\n      +'</div>'\n      +'<div style=\"margin-top:18px;font-size:12px;font-weight:700\">'+tbar+'선호 장르 <span style=\"font-weight:400;color:var(--dim)\">(관람 '+fmt(tot)+'회 · 장부 기준)</span></div>'\n      +'<div style=\"margin-top:9px;display:flex;flex-wrap:wrap;gap:6px\">'+chips+'</div>'\n      +'<div style=\"margin-top:18px;font-size:12px;font-weight:700\">'+tbar+'연도별 관람</div>'\n      +'<div style=\"margin-top:10px;display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap\">'+bars+'</div>';\n  }catch(e){console.warn('[mem-detail]',e);}\n}\nfunction _memRender(){"''')),
